function landingRecorder(){return `<div class="flight-window"><div class="window-bar"><span class="window-label">${icon('wave')} Studio Nord <span class="muted">/ Flugschreiber</span></span><div class="window-meta"><span class="mono">DEMO WORKSPACE</span><span class="live-label"><i class="dot pulse"></i>Live-Simulation</span></div></div><div class="pipeline"><div class="pipe-sources"><span class="tiny-label">01 / Deine Quellen</span>${sources.slice(0,4).map(s=>`<div class="source-pill">${sourceIcon(s.id)}${s.short}</div>`).join('')}</div><div class="pipe-timeline"><div class="timeline-caption"><span class="tiny-label">02 / Dein Business-Gedächtnis</span><span class="record-count">APPEND · CONNECT · REMEMBER</span></div><div class="scan-head"></div>${tracks.map((t,i)=>{const choices=[['SRC-001','SRC-002','SRC-003'],['FAC-001','FAC-003'],['COM-002','COM-003'],['MOV-001','MOV-002'],['RES-001','RES-003']][i];return `<div class="mini-track"><span class="mini-track-label">${t.label}</span>${choices.map(id=>{const e=events.find(e=>e.id===id);return `<button class="mini-event" data-action="event" data-id="${id}">${e.title}</button>`}).join('')}</div>`}).join('')}</div><div class="pipe-answer"><span class="tiny-label">03 / Klare Antworten</span><div class="agent-row"><span class="agent-emblem">${icon('spark')}</span>Dein Agent · via MCP</div><div class="answer-question">„Wie viel kann ich heute noch verkaufen?“</div><div class="mini-answer"><b>86 Stück.</b><br>120 im Lager. 34 reserviert.<br>Mit jedem Beleg dahinter.</div><div class="mini-citations"><span>↗ API-Import</span><span>↗ Shopify</span></div></div></div><div class="window-footer"><span><i class="dot"></i>5 SPUREN · EIN ZUSAMMENHANG</span><span>JEDES EREIGNIS BLEIBT. JEDE ANTWORT HAT EINE QUELLE.</span><span>10:42:00 CET</span></div></div>`}
function renderLanding(){document.title='blackbox — Dein Business. Lückenlos.';document.getElementById('root').innerHTML=`<div class="wrap"><nav class="site-nav" aria-label="Hauptnavigation"><a href="#" aria-label="blackbox Startseite">${brand()}</a><div class="nav-links"><a href="#prinzip">Das Prinzip</a><a href="#flugschreiber">Der Flugschreiber</a><a href="#agenten">Für Agenten</a></div><div class="nav-actions"><button class="btn ghost" data-action="signup">Anmelden</button><button class="btn primary" data-action="demo">Live-Demo öffnen ${icon('arrow')}</button></div></nav><main><section class="hero"><div class="eyebrow"><i class="dot"></i>DAS GEDÄCHTNIS FÜR DEIN HANDELSBUSINESS</div><h1>Dein Business läuft.<br><em>Die Wahrheit bleibt.</em></h1><p class="hero-copy">Bestellungen, E-Mails, Warenbewegungen. Ein Flugschreiber, der alles zusammenbringt. Damit du und deine Agenten wissen, was wirklich los ist.</p><div class="hero-buttons"><button class="btn primary" data-action="signup">Flugschreiber starten ${icon('arrow')}</button><button class="btn secondary" data-action="demo">${icon('play')} Mit Beispieldaten erleben</button></div><div class="micro"><span>${icon('check')} In 60 Sekunden verstanden</span><span>${icon('check')} Ohne Zugangsdaten ausprobieren</span></div>${landingRecorder()}<div class="source-band"><span class="label">Deine Tools. Ein gemeinsames Gedächtnis.</span><strong><i style="color:#8aa264">S</i> Shopify</strong><strong>${icon('mail')} E-Mail</strong><strong>Shopware 6</strong><strong>DHL · DPD · UPS</strong><strong>Rechnungen & Buchhaltung</strong><strong>Payments</strong><span class="plus-more">+ jede API</span></div></section><section class="principle-section" id="prinzip"><div class="section-intro"><div><div class="eyebrow">WENIGER SUCHEN. MEHR WISSEN.</div><h2>Ein Geschäft.<br>Endlich ein Zusammenhang.</h2></div><p>Dein Shop kennt die Bestellung. Dein ERP den Bestand. Dein Postfach die neue Lieferzusage. blackbox verbindet die Geschichte.</p></div><div class="step-grid"><article class="step"><div class="step-no">01 ${icon('plug')}</div><h3>Quellen verbinden.</h3><p>Shop, E-Mail, ERP und Rechnungstool liefern die Ereignisse. Das Original bleibt mit Zeitstempel erhalten.</p></article><article class="step"><div class="step-no">02 ${icon('wave')}</div><h3>Business verstehen.</h3><p>Was ist Fakt, was zugesagt, was bewegt und was reserviert? Fünf parallele Spuren machen den Unterschied sichtbar.</p></article><article class="step"><div class="step-no">03 ${icon('spark')}</div><h3>Bessere Fragen stellen.</h3><p>Du fragst. Dein Agent findet den Zusammenhang – mit Quellen, aktuellem Stand und klar benannten Lücken.</p></article></div></section></main></div><section class="tracks-section" id="flugschreiber"><div class="wrap tracks-layout"><div class="tracks-copy"><div class="eyebrow">DER BUSINESS-FLUGSCHREIBER</div><h2>Nichts geht verloren.<br>Alles hängt zusammen.</h2><p>Ein fortlaufendes Protokoll deines Business. Neue Ereignisse kommen hinzu. Änderungen ersetzen die Historie nicht – sie erklären sie.</p><button class="text-link" data-action="demo">Den Flugschreiber entdecken ${icon('arrow')}</button></div><div class="track-explainer">${tracks.map((t,i)=>`<div class="track-explain-row"><span class="track-number">0${i+1}</span><span class="track-title"><i style="background:${t.color}"></i>${t.label}</span><span class="track-description">${t.description}</span></div>`).join('')}</div></div></section><div class="wrap"><section class="questions-section"><div class="questions-layout"><div class="questions-copy"><div class="eyebrow">FRAG DEIN BUSINESS.</div><h2>Keine Vermutung.<br>Eine Antwort mit Belegen.</h2><div class="example-buttons">${[['inventory','Kann ich noch 100 Olive Cups verkaufen?'],['delivery','Welche Lieferung ist verspätet?'],['cash','Wie steht es nächste Woche um mein Cash?'],['tracking','Wo sind meine Pakete?'],['billing','Welche Rechnungen sind noch offen?'],['payments','Wo steckt mein Geld bei den Payment-Providern?']].map(([id,label])=>`<button class="example-button ${state.landingExample===id?'active':''}" data-action="landing-question" data-id="${id}">${label}${icon('arrow')}</button>`).join('')}</div></div><div class="answer-preview" id="landing-answer"><div class="answer-preview-head"><span>${icon('spark')} blackbox / Antwort aus Beispieldaten</span>${icon('shield')}</div>${answerHTML(state.landingExample,true)}</div></div></section><section class="agents-banner" id="agenten"><div><div class="eyebrow">DEIN AGENT. DEIN KONTEXT.</div><h2>Eine Wahrheit.<br>Für jeden deiner Agenten.</h2><p>Über MCP bekommt dein Agent denselben nachvollziehbaren Business-Kontext. Ob Claude, ChatGPT oder dein eigener Agent.</p><button class="btn lime" data-action="open-agent">Agenten-Anbindung erleben ${icon('arrow')}</button></div><div class="agent-network"><div class="network-core">${icon('wave')}</div><div class="network-line"></div><div class="network-agents"><span class="network-agent">${icon('spark')}Claude</span><span class="network-agent">${icon('message')}ChatGPT</span><span class="network-agent">${icon('code')}Dein Agent</span></div></div></section><footer class="site-footer"><a href="#">${brand()}</a><p>Dein Business. Lückenlos.<br>Produktkonzept · Interaktiver Prototyp mit Beispieldaten.</p><div class="footer-links"><button data-action="about">Über die Demo</button><a href="#prinzip">Das Prinzip</a><button data-action="demo">App öffnen ↗</button></div></footer></div>`}
const navItems=[['recorder','wave','Flugschreiber'],['sources','plug','Quellen'],['answers','spark','Fragen & Antworten'],['agents','code','Agenten & MCP'],['history','list','Ereignisprotokoll']];
function renderApp(){document.title=`${navItems.find(n=>n[0]===state.tab)?.[2]||'Flugschreiber'} — blackbox`;document.getElementById('root').innerHTML=`<div class="app-layout"><div class="mobile-sidebar-overlay ${state.mobileMenu?'open':''}" data-action="menu"></div><aside class="sidebar ${state.mobileMenu?'mobile-open':''}"><a href="#">${brand()}</a><div class="workspace-switch"><span class="workspace-avatar">${escapeHtml(state.workspace.slice(0,1).toUpperCase())}</span><div>${escapeHtml(state.workspace)}<small>Commerce Workspace</small></div></div><div class="sidebar-label">DEIN BUSINESS-GEDÄCHTNIS</div><nav class="side-nav" aria-label="Anwendung">${navItems.map(([id,ic,label])=>`<button class="nav-item ${state.tab===id?'active':''}" data-action="tab" data-id="${id}" ${state.tab===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='recorder'?'<span class="nav-counter">5</span>':''}</button>`).join('')}</nav><div class="side-divider"></div><button class="nav-item" data-action="onboarding">${icon('play')}Kurze Tour starten</button><div class="sidebar-note"><div class="eyebrow"><i class="dot pulse"></i>DEIN BUSINESS. LÜCKENLOS.</div><p>Jedes Ereignis bleibt.<br>Jede Antwort hat eine Quelle.</p></div><div class="sidebar-bottom"><button data-action="landing">${icon('exit')} Zur Landingpage</button><button data-action="about" aria-label="Informationen zur Demo">${icon('info')}</button></div></aside><div class="app-main"><header class="app-topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu-btn" data-action="menu" aria-label="Navigation öffnen">${icon('menu')}</button>${escapeHtml(state.workspace)}<span>/</span><strong>${navItems.find(n=>n[0]===state.tab)?.[2]}</strong></div><div class="topbar-right"><span class="demo-badge">DEMO · BEISPIELDATEN</span><span class="live-label"><i class="dot"></i>System bereit</span><span class="user-avatar">SN</span></div></header><main class="app-content" id="app-content">${renderTab()}</main></div></div>`}
function renderTab(){if(state.tab==='sources')return sourcesPage();if(state.tab==='agents')return agentsPage();if(state.tab==='history')return historyPage();if(state.tab==='answers')return answersPage();return dashboard()}
function pageHeading(title,desc,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function dashboard(){return `${pageHeading('Dein Business. Jetzt im Bild.','Alles, was passiert. Alles, was zählt. An einem Ort.',`<button class="btn secondary small" data-action="export">${icon('download')} Export</button><button class="btn primary small" data-action="tab" data-id="sources">${icon('plus')} Quelle verbinden</button>`)}<div class="stats-grid"><div class="stat"><div class="stat-label">Verbundene Quellen ${icon('plug')}</div><div class="stat-value">${state.sources.length}<small>Demo-Verbindungen</small></div><div class="stat-foot"><i class="dot"></i>${state.sources.length?'Für Simulation aktiviert':'Noch keine Quelle aktiviert'}</div></div><div class="stat"><div class="stat-label">Aufgezeichnete Ereignisse ${icon('wave')}</div><div class="stat-value" id="stat-events">${events.length}<small>in diesem Demo-Lauf</small></div><div class="stat-foot">${icon('arrow')}Historie bleibt erhalten</div></div><div class="stat"><div class="stat-label">Offene Commitments ${icon('clock')}</div><div class="stat-value">${2+invoiceTotals().count+paymentDemo.filter(p=>latestPayment(p).expected>0).length}<small>nachzuverfolgen</small></div><div class="stat-foot" style="color:#ae925f">${icon('info')}1 Liefertermin verschoben</div></div><div class="stat"><div class="stat-label">Freier Bestand · Olive Cup ${icon('box')}</div><div class="stat-value">86<small>von 120 Stück</small></div><div class="stat-foot">${icon('lock')}34 Stück reserviert</div></div></div><section class="recorder" aria-label="Fortlaufender Business-Flugschreiber">${recorderHTML()}</section><div class="dashboard-lower">${askPanel()}<section class="activity-panel"><div class="panel-head"><span>${icon('clock')}Was gerade zählt</span><small>31. Oktober 2026</small></div><button class="activity-item" data-action="event" data-id="COM-002" style="text-align:left;width:100%"><span class="activity-symbol" style="color:#aa90be">${icon('clock')}</span><div><strong>Eine Zusage hat sich geändert.</strong><p>80 Olive Cups kommen am 05.11. statt 03.11.</p></div><time>10:39</time></button><button class="activity-item" data-action="event" data-id="FAC-003" style="text-align:left;width:100%"><span class="activity-symbol">${icon('box')}</span><div><strong>86 Stück sind wirklich verfügbar.</strong><p>Physischer Bestand minus offene Reservierungen.</p></div><time>10:40</time></button><button class="activity-item" data-action="tab" data-id="agents" style="text-align:left;width:100%"><span class="activity-symbol">${icon('spark')}</span><div><strong>Dieser Kontext ist für Agenten gedacht.</strong><p>Erkunde die Verbindung über MCP.</p></div>${icon('arrow')}</button></section></div><div class="context-note"><span>Simulierte Ereignisse · 31.10.2026 · Europe/Rome · Nur in dieser Browser-Sitzung</span><span>Demo-Modell: Quellen → Fakten → nachvollziehbare Antworten</span></div>`}
function recorderHTML(){return `<div class="recorder-header"><div class="recorder-title">${icon('wave')}Business-Flugschreiber<span class="live-label"><i class="dot ${state.paused?'':'pulse'}"></i>${state.paused?'Pausiert':'Live'}</span></div><div class="recorder-tools"><span class="recording-status">${state.sources.length?state.sources.length+' QUELLEN AKTIV':'KEINE QUELLE AKTIV'}</span><button class="icon-btn" data-action="pause" aria-label="${state.paused?'Simulation fortsetzen':'Simulation pausieren'}" title="${state.paused?'Fortsetzen':'Pausieren'}">${icon(state.paused?'play':'pause')}</button><button class="btn secondary small" data-action="simulate">${icon('plus')} Ereignis</button></div></div><div class="recorder-ruler"><span class="ruler-caption">5 PARALLELE SPUREN</span><div class="ruler-times"><span>10:38:00</span><span>10:40:00</span><span id="live-time">${currentTime()} · JETZT</span></div></div><div id="track-rows">${trackRows()}</div><div class="recorder-bottom"><span>${icon('shield')}ORIGINAL + HERKUNFT + ZEITSTEMPEL</span><button data-action="tab" data-id="history">Alle Ereignisse ansehen ↗</button></div>`}
function trackRows(){return tracks.map((t,i)=>{const ee=events.filter(e=>e.type===t.id&&e.status!=='Ersetzt'&&paymentEventIsCurrent(e)&&(!e.id.startsWith('COM-BILL-')||invoiceDemo.some(invoice=>latestInvoice(invoice).commitmentId===e.id))).slice(-2);return `<div class="track-row" style="${trackStyle(t.id)}"><div class="track-name"><i></i>${t.label}<small>${events.filter(e=>e.type===t.id).length}</small></div><div class="track-lane" style="--offset:${[0,18,32,10,23][i]}px">${ee.map(e=>`<button class="event-chip ${e.live?'new-event':''}" data-action="event" data-id="${e.id}">${icon(t.icon)}<span>${e.title}</span><time>${e.time.slice(0,5)}</time></button>`).join('')}</div></div>`}).join('')}
function askPanel(){return `<section class="ask-panel"><div class="panel-head"><span>${icon('spark')}Frag deinen Flugschreiber</span><small>DEMO-ASSISTENT</small></div><p>Stelle eine Frage. Die Antwort kennt den Zusammenhang und zeigt dir die Quellen.</p><form class="question-form" id="question-form"><input id="question-input" name="question" aria-label="Frage an den Flugschreiber" placeholder="Was möchtest du über dein Business wissen?" autocomplete="off" required maxlength="500"><button type="submit" aria-label="Frage stellen">${icon('arrow')}</button></form><div class="question-suggestions"><button data-action="ask" data-id="inventory">Kann ich noch 100 Stück verkaufen?</button><button data-action="ask" data-id="delivery">Welche Lieferung ist verspätet?</button><button data-action="ask" data-id="cash">Wie steht es um mein Cash?</button><button data-action="ask" data-id="tracking">Wo sind meine Pakete?</button><button data-action="ask" data-id="billing">Welche Rechnungen sind noch offen?</button><button data-action="ask" data-id="payments">Wo steckt mein Geld bei den Providern?</button></div><div class="ask-foot">${icon('shield')}Antworten aus Demo-Daten · Keine externe KI-Verbindung</div><div id="answer-container" aria-live="polite">${state.answer?answerHTML(state.answer):''}</div></section>`}
function answersPage(){return `${pageHeading('Gute Fragen. Belegbare Antworten.','Ein gemeinsamer Kontext für dich und deine Agenten.')}<div class="answers-page">${askPanel()}<div class="info-strip">${icon('info')}Die Demo beantwortet drei vorbereitete Business-Szenarien sowie Paketstatus, Rechnungs- und Zahlungsstände aus den aktuellen Demo-Ereignissen. Unbekannte Fragen werden als Datenlücke angezeigt. Ein echtes Produkt würde Quellen über einen Agenten auswerten.</div></div>`}
function sourceCard(s){const connected=state.sources.includes(s.id);return `<article class="integration-card"><div class="integration-top">${sourceIcon(s.id)}<span class="connection-state">${s.comingSoon?'Coming Soon':connected?'<i class="dot"></i>Demo aktiv':'Demo verfügbar'}</span></div><h2>${s.name}</h2><p>${s.text}</p><div class="integration-info">${s.meta}</div><button class="btn ${connected||s.comingSoon?'secondary':'primary'}" data-action="connect" data-id="${s.id}" ${s.comingSoon?'disabled':''}>${s.comingSoon?icon('clock')+'Coming Soon':connected?icon('sliders')+'Verbindung verwalten':icon('plus')+'Demo-Quelle verbinden'}</button>${s.category==='billing'?`<button class="billing-card-link" data-action="billing-detail" data-id="${s.id}">Rechnungsverlauf erleben ${icon('arrow')}</button>`:s.category==='payment'?`<button class="billing-card-link" data-action="payment-detail" data-id="${s.id}">Zahlungsverlauf erleben ${icon('arrow')}</button>`:s.category==='tracking'?carrierSourceAction(s):''}</article>`}
function sourcesPage(){return `${pageHeading('Dein Business hat viele Quellen.','Verbinde sie zu einer gemeinsamen Geschichte. Neue Ereignisse landen auf den passenden Spuren.',`<button class="btn secondary small" data-action="onboarding">${icon('play')}Einrichtung ansehen</button>`)}${sourceJumpLinks()}<section class="source-group" id="source-shops"><div class="source-group-heading"><div><h2>Shops & Business</h2><p>Aufträge, Artikel, Belege und Zusagen aus deinen Systemen.</p></div></div><div class="app-section-grid">${sources.filter(s=>!['tracking','billing','payment'].includes(s.category)).map(sourceCard).join('')}</div></section>${paymentSourcesSection()}<section class="source-group billing-source-group" id="source-billing"><div class="source-group-heading"><div><h2>Rechnungen & Buchhaltung</h2><p>Rechnung, Mahnung, Korrektur und Zahlungsstatus. Jede Änderung wird Teil der Geschichte.</p></div><button class="btn secondary small" data-action="billing-question">${icon('spark')}Offene Rechnungen prüfen</button></div><div class="billing-flow-strip"><span>${icon('list')}Originalbeleg</span>${icon('arrow')}<span>${icon('check')}Belegbarer Fact</span>${icon('arrow')}<span>${icon('clock')}Aktueller Forderungsstand</span></div><div class="app-section-grid">${sources.filter(s=>s.category==='billing').map(sourceCard).join('')}</div></section><section class="source-group" id="source-tracking"><div class="source-group-heading"><div><h2>Versandquellen</h2><p>Statusmeldungen von DHL, DPD und UPS fließen als Sources und Facts in deinen gemeinsamen Flugschreiber.</p></div></div><div class="app-section-grid">${sources.filter(s=>s.category==='tracking').map(sourceCard).join('')}</div></section><div class="info-strip">${icon('shield')}Alle Verbindungen sind simuliert. Es werden keine Shop-, Payment-, Rechnungs-, E-Mail-, ERP- oder Carrier-Zugangsdaten abgefragt. Bereits aufgezeichnete Demo-Ereignisse bleiben nach dem Trennen einer Quelle erhalten.</div>`}

const configText=()=>JSON.stringify({mcpServers:{blackbox:{url:'https://api.example.com/mcp',headers:{Authorization:'Bearer <DEIN_READ_ONLY_TOKEN>'}}}},null,2);
function agentsPage(){return `${pageHeading('Dein Agent. Mit Business-Gedächtnis.','Ein MCP-Zugang macht denselben Kontext für verschiedene Agenten nutzbar.',`<button class="btn secondary small" data-action="otc-jump">${icon('spark')}24 Agenten-Fragen</button>`)}<div class="agent-config-layout"><section class="white-panel"><h2>Agenten-Anbindung</h2><p>Wähle einen Agenten und erkunde den vorgesehenen Verbindungsweg.</p><div class="agent-options">${['Claude','ChatGPT','Eigener Agent'].map((a,i)=>`<button class="agent-option ${state.agent===a?'selected':''}" data-action="agent" data-id="${a}">${icon(['spark','message','code'][i])}${a}</button>`).join('')}</div><div class="form-label">MCP-Endpunkt</div><div class="config-code">https://api.example.com/mcp</div><div class="demo-callout">Konzeptansicht: Dieser Endpunkt ist ein Platzhalter. Im Prototyp läuft kein MCP-Server. Das Beispiel zeigt die geplante Struktur.</div><div class="permission-list"><span>${icon('check')}Lesen: Ereignisse, aktueller Stand und Belege</span><span>${icon('check')}Kontext: ${escapeHtml(state.workspace)} / alle fünf Spuren</span><span>${icon('lock')}Geplant: Workspace-begrenzt, nur Lesezugriff</span></div><button class="btn primary full" data-action="test-agent">${icon('play')}Agenten-Abfrage simulieren</button></section><section class="white-panel"><h2>${state.agent==='Eigener Agent'?'Deinen Agenten verbinden':state.agent+' verbinden'}</h2><p>So ist der Ablauf im Produkt gedacht. Die genaue Einrichtung hängt vom jeweiligen MCP-Client ab.</p><div class="numbered-step"><span>1</span><div><b>MCP-Verbindung hinzufügen</b><br>Im Agenten einen Remote-MCP-Server anlegen.</div></div><div class="numbered-step"><span>2</span><div><b>Workspace freigeben</b><br>Mit dem vorgesehenen Zugriff auf deinen Business-Kontext verbinden.</div></div><div class="numbered-step"><span>3</span><div><b>Dein Business fragen</b><br>Zum Beispiel: „Kann ich noch 100 Olive Cups verkaufen?“</div></div><div class="code-head"><span>SCHEMATISCHE KONFIGURATION</span><button data-action="copy-config">${icon('copy')} Kopieren</button></div><pre class="config-code">${escapeHtml(configText())}</pre></section></div><section class="white-panel" style="margin-top:22px"><h2>Die Werkzeuge für den gemeinsamen Kontext</h2><p>Vorgesehener MCP-Vertrag. Jede Antwort soll auf Ereignisse im Flugschreiber zurückführen.</p><div class="app-section-grid tools-list"><div class="tool-row"><code>search_events(query, as_of)</code><p>Ereignisse nach Thema, Entität und Zeitpunkt finden.</p></div><div class="tool-row"><code>get_business_state(entity, as_of)</code><p>Bestand, Zusagen und Reservierungen getrennt lesen.</p></div><div class="tool-row"><code>get_evidence(event_id)</code><p>Originalquelle und Ableitung einer Aussage abrufen.</p></div></div></section>${otcExamplesSection()}`}
function filteredEvents(){const q=state.historySearch.trim().toLowerCase();return events.filter(e=>(state.historyType==='all'||e.type===state.historyType)&&(!q||[e.id,e.title,e.entity,e.source,e.detail].join(' ').toLowerCase().includes(q))).slice().reverse()}
function ledgerRows(){const filtered=filteredEvents();return filtered.length?filtered.map(e=>`<tr data-action="event" data-id="${e.id}"><td><button class="text-link" data-action="event" data-id="${e.id}" style="font:9px var(--mono)">${e.id}</button></td><td>${e.time}</td><td><span class="type-tag" style="${trackStyle(e.type)}">${trackById(e.type).singular}</span></td><td>${e.title}${e.status==='Ersetzt'?' <span class="muted">· ersetzt</span>':''}</td><td>${e.source}</td><td>${icon('chevron')}</td></tr>`).join(''):`<tr><td colspan="6" class="empty-state">Keine Ereignisse für diese Auswahl. Passe Suche oder Spur an.</td></tr>`}
function historyPage(){return `${pageHeading('Jedes Ereignis hat eine Geschichte.','Originale, Ableitungen und Änderungen bleiben gemeinsam nachvollziehbar.',`<button class="btn secondary small" data-action="export">${icon('download')}JSON exportieren</button>`)}<div class="history-toolbar"><input class="field" id="history-search" placeholder="Ereignis, Artikel oder Quelle suchen …" aria-label="Ereignisse durchsuchen" value="${escapeHtml(state.historySearch)}"><select id="history-type" aria-label="Spur filtern"><option value="all">Alle fünf Spuren</option>${tracks.map(t=>`<option value="${t.id}" ${state.historyType===t.id?'selected':''}>${t.label}</option>`).join('')}</select><span class="mono muted" id="history-count">${filteredEvents().length} Ereignisse</span></div><div class="ledger-table-wrap"><table class="ledger-table"><thead><tr><th>ID</th><th>Zeit</th><th>Spur</th><th>Ereignis</th><th>Quelle</th><th></th></tr></thead><tbody id="ledger-body">${ledgerRows()}</tbody></table></div><div class="info-strip">${icon('clock')}Demo-Zeitraum: 31.10.2026. Die Historie enthält auch ersetzte Zusagen. In einer Antwort gilt jeweils der letzte bekannte Stand – die ursprüngliche Information bleibt sichtbar.</div>`}
function route(){const hash=location.hash;if(hash==='#app/tracking'){location.replace('#app/sources');return}if(hash.startsWith('#app')){state.page='app';const tab=hash.split('/')[1]||'recorder';state.tab=navItems.some(n=>n[0]===tab)?tab:'recorder';state.mobileMenu=false;renderApp();window.scrollTo(0,0)}else{if(state.page!=='landing'||!document.querySelector('.site-nav')){state.page='landing';renderLanding()}if(hash&&hash!=='#'){requestAnimationFrame(()=>document.getElementById(hash.slice(1))?.scrollIntoView({behavior:'smooth'}))}}}
function navigate(tab='recorder'){closeOverlay();if(location.hash===`#app/${tab}`){state.page='app';state.tab=tab;state.mobileMenu=false;renderApp();window.scrollTo(0,0)}else location.hash=`app/${tab}`}
let priorFocus=null;
function showOverlay(html,drawer=false){if(!document.getElementById('overlay-root').children.length)priorFocus=document.activeElement;document.getElementById('overlay-root').innerHTML=drawer?`<div class="drawer-backdrop" data-dismiss="true"><aside class="detail-drawer" role="dialog" aria-modal="true" aria-label="Ereignisdetails">${html}</aside></div>`:`<div class="modal-backdrop" data-dismiss="true"><section class="modal" role="dialog" aria-modal="true" aria-label="${state.onboardStep?'Flugschreiber einrichten':'blackbox Demo'}">${html}</section></div>`;document.body.style.overflow='hidden';document.getElementById('root').inert=true;requestAnimationFrame(()=>{document.querySelector('#overlay-root input,#overlay-root button')?.focus()})}
function closeOverlay(){document.getElementById('overlay-root').innerHTML='';document.body.style.overflow='';document.getElementById('root').inert=false;if(priorFocus?.isConnected)priorFocus.focus();priorFocus=null}
const closeButton=()=>`<button class="icon-btn modal-close" data-action="close" aria-label="Schließen">${icon('close')}</button>`;
function showSignup(){state.onboardStep=0;showOverlay(`${closeButton()}${brand()}<div class="eyebrow" style="margin-bottom:14px;color:#8ca475">DEIN BUSINESS VERDIENT EIN GEDÄCHTNIS.</div><h2>Einmal verbinden.<br>Den Überblick behalten.</h2><p>Erlebe deinen Flugschreiber in einem eigenen Demo-Workspace. Ganz ohne Passwort.</p><form id="signup-form"><label class="form-label" for="workspace-name">Wie heißt dein Business?</label><input class="field" id="workspace-name" name="workspace" placeholder="Zum Beispiel Studio Nord" value="${escapeHtml(state.workspace)}" required maxlength="50"><button class="btn primary full" type="submit">Demo-Workspace einrichten ${icon('arrow')}</button></form><div class="divider-word">ODER DIREKT EINSTEIGEN</div><button class="btn secondary full" data-action="demo">${icon('play')}Studio Nord mit Beispieldaten öffnen</button><p class="fineprint">Prototyp: kein echtes Konto, keine Zugangsdaten.<br>Dein Workspace-Name wird nur in diesem Browser gespeichert.</p>`)}
function showOnboarding(step=1){state.onboardStep=step;let body='';if(step===1)body=`<div class="eyebrow" style="color:#8ca475;margin-bottom:12px">01 / QUELLEN VERBINDEN</div><h2>Wo passiert dein Business?</h2><p>Wähle die Demo-Quellen für ${escapeHtml(state.workspace)}. Du kannst später weitere hinzufügen.</p>${sources.filter(s=>['shopify','shopware','email'].includes(s.id)).map(s=>`<label class="onboard-source">${sourceIcon(s.id)}<span><strong>${s.name}</strong><small>${s.comingSoon?'Coming Soon':s.subtitle}</small></span><input type="checkbox" name="onboard-source" value="${s.id}" ${!s.comingSoon&&state.selectedSources.includes(s.id)?'checked':''} ${s.comingSoon?'disabled':''}></label>`).join('')}<div class="demo-callout">Diese Auswahl simuliert die Verbindung. Es werden keine echten Konten angebunden.</div><div class="onboard-actions"><button class="btn primary full" data-action="onboard-next">Quellen aktivieren ${icon('arrow')}</button></div>`;if(step===2)body=`<div class="eyebrow" style="color:#8ca475;margin-bottom:12px">02 / DEIN FLUGSCHREIBER LÄUFT</div><h2>Aus Ereignissen<br>wird Zusammenhang.</h2><p>Ein Auftrag bleibt nicht nur eine Zeile in deinem Shop. Er bekommt Kontext.</p><div class="flow-summary"><div>${icon('plug')}<span>Bestellung #1042 kommt an.<small>Shopify · Original mit Zeitstempel</small></span></div><div>${icon('check')}<span>12 Olive Cups wurden bestellt.<small>Fact · Extrahiert aus dem Auftrag</small></span></div><div>${icon('lock')}<span>12 Stück werden reserviert.<small>Reservation · 34 Stück insgesamt gebunden</small></span></div><div>${icon('spark')}<span>86 Stück sind noch verfügbar.<small>120 physisch − 34 reserviert</small></span></div></div><div class="onboard-actions"><button class="btn secondary" data-action="onboard-back">Zurück</button><button class="btn primary" style="flex:1" data-action="onboard-next">Und mein Agent? ${icon('arrow')}</button></div>`;if(step===3)body=`<div class="eyebrow" style="color:#8ca475;margin-bottom:12px">03 / FRAGEN STATT SUCHEN</div><h2>Dein Agent kennt<br>jetzt den Zusammenhang.</h2><p>Im vorgesehenen Produkt nutzt dein Agent über MCP den Flugschreiber als gemeinsame Wissensquelle.</p><div class="agent-options">${['Claude','ChatGPT','Eigener Agent'].map((a,i)=>`<button class="agent-option ${state.agent===a?'selected':''}" data-action="onboard-agent" data-id="${a}">${icon(['spark','message','code'][i])}${a}</button>`).join('')}</div><div class="evidence-box"><h3>„Kann ich noch 100 Olive Cups verkaufen?“</h3><blockquote>86 Stück sind frei verfügbar. Für 100 fehlen 14. Die erwartete Lieferung zählt noch nicht als Bestand.</blockquote></div><div class="demo-callout">Die Demo zeigt den Ablauf mit vorbereiteten Antworten. MCP-Server und echte Anmeldung sind noch nicht implementiert.</div><div class="onboard-actions"><button class="btn secondary" data-action="onboard-back">Zurück</button><button class="btn primary" style="flex:1" data-action="finish-onboard">Flugschreiber öffnen ${icon('arrow')}</button></div>`;showOverlay(`${closeButton()}${brand()}<div class="onboard-progress">${[1,2,3].map(i=>`<span class="${i<=step?'active':''}"></span>`).join('')}</div>${body}`)}
function eventDetail(id){const e=events.find(e=>e.id===id);if(!e)return;const t=trackById(e.type);showOverlay(`${closeButton()}<div class="eyebrow">${icon(t.icon)}EREIGNIS IM FLUGSCHREIBER</div><h2>${e.title}</h2><p>${e.detail}</p><span class="type-tag detail-type" style="${trackStyle(e.type)}">${t.singular}${e.status?' · '+e.status:''}</span><dl class="detail-meta"><div><dt>Ereignis-ID</dt><dd class="mono">${e.id}</dd></div><div><dt>Aufgezeichnet</dt><dd>31.10.2026, ${e.time} CET</dd></div><div><dt>Quelle</dt><dd>${e.source}</dd></div><div><dt>Bezug</dt><dd>${e.entity}</dd></div><div><dt>Herkunft</dt><dd>${e.proof}</dd></div></dl><div class="evidence-box"><h3>${e.type==='source'?'Originalauszug':'Beleg / Ableitung'}</h3><blockquote>${escapeHtml(e.quote)}</blockquote></div><div class="eyebrow" style="font-size:9px;margin:25px 0 7px">VERKNÜPFTE EREIGNISSE</div>${(e.related||[]).map(id=>{const r=events.find(e=>e.id===id);return r?`<button class="detail-link" data-action="event" data-id="${id}"><span><span class="mono muted">${id}</span><br><span style="display:inline-block;margin-top:4px">${r.title}</span></span>${icon('arrow')}</button>`:''}).join('')}<div class="demo-callout">Beispieldaten zur Erklärung des Produktkonzepts. Hier werden keine echten Geschäftsdaten verarbeitet.</div>`,true)}
function connectionModal(id){const s=sources.find(s=>s.id===id);if(!s||s.comingSoon)return;if(s.category==='billing'){billingConnectionModal(s);return}if(s.category==='payment'){paymentConnectionModal(s);return}const connected=state.sources.includes(id);showOverlay(`${closeButton()}<div style="margin-bottom:22px">${sourceIcon(id)}</div><h2>${s.name} ${connected?'ist aktiviert.':'verbinden.'}</h2><p>${s.text}</p><div class="flow-summary"><div>${icon('plug')}<span>Quelle erkennen<small>${s.meta}</small></span></div><div>${icon('wave')}<span>Ereignisse dem Flugschreiber hinzufügen<small>Mit Quellen-ID, Zeitpunkt und Original</small></span></div><div>${icon('spark')}<span>Belegbaren Kontext gewinnen<small>Fakten, Zusagen, Bewegungen und Reservierungen</small></span></div></div><div class="demo-callout">Demo-Verbindung: Der Schalter aktiviert simulierte Ereignisse dieser Quelle. Es erfolgt keine echte Autorisierung bei ${s.name}.</div><button class="btn ${connected?'secondary':'primary'} full" data-action="toggle-source" data-id="${id}">${connected?'Demo-Quelle trennen':'Demo-Quelle aktivieren'}${icon(connected?'exit':'arrow')}</button>`)}
function about(){showOverlay(`${closeButton()}${brand()}<h2>Ein Produkt zum Anfassen.</h2><p>blackbox ist ein interaktiver Prototyp für einen Business-Flugschreiber. Alle Geschäftsdaten stammen aus dem fiktiven Shop „Studio Nord“.</p><div class="flow-summary"><div>${icon('check')}<span>Was du ausprobieren kannst<small>Onboarding, Live-Stream, Belege, Quellenwahl, Suche, JSON-Export und Business-Antworten, Carrier-Ereignisse im Flugschreiber, Rechnungsverläufe und Payment-Ereignisse.</small></span></div><div>${icon('code')}<span>Was als Nächstes gebaut würde<small>Echte Anmeldung, Konnektoren, dauerhafte Ereignisspeicherung, Extraktion und ein authentifizierter MCP-Server.</small></span></div></div><p>Nur Workspace-Name und Quellenauswahl werden lokal gespeichert. Der Ereignisstrom startet beim Neuladen neu.</p><button class="btn primary full" data-action="close">Verstanden ${icon('check')}</button>`)}
function showAnswer(type){state.answer=type;const target=document.getElementById('answer-container');if(target){target.innerHTML=answerHTML(type);const a=getAnswer(type);const input=document.getElementById('question-input');if(input&&a.question)input.value=a.question;target.scrollIntoView({behavior:'smooth',block:'nearest'})}}
function addLiveEvent(manual=false){if(!state.sources.length){if(manual)toast('Aktiviere zuerst eine Demo-Quelle.');return}state.liveIndex++;const enabled=state.sources.map(id=>sources.find(s=>s.id===id));const s=enabled[(state.liveIndex-1)%enabled.length];const id=`LIVE-${String(state.liveIndex).padStart(3,'0')}`;const isFact=state.liveIndex%2===0;const e={id,type:isFact?'fact':'source',title:isFact?`${s.short} · Snapshot unverändert`:`${s.short} · Abgleich empfangen`,source:s.name,time:currentTime(),entity:'Demo-Synchronisierung',detail:`Simulierter Abgleich von ${s.name}. Die bestehenden Demo-Daten wurden erneut bestätigt. Dieser Eintrag ändert keine Bestände, Reservierungen oder Zusagen.`,quote:`Demo-Snapshot bestätigt um ${currentTime()}. Keine neue Geschäftsbewegung.`,related:s.id==='shopify'?['SRC-001','RES-001']:s.id==='email'?['SRC-002','COM-002']:s.id==='api'?['SRC-003','FAC-003']:[],proof:'Simuliertes Synchronisierungsereignis',live:true};events.push(e);if(state.tab==='recorder'&&state.page==='app'){const rows=document.getElementById('track-rows');if(rows)rows.innerHTML=trackRows();const stat=document.getElementById('stat-events');if(stat)stat.innerHTML=`${events.length}<small>in diesem Demo-Lauf</small>`}if(state.tab==='history'&&state.page==='app')refreshLedger();if(manual)toast(`${s.name}: Neues Demo-Ereignis aufgezeichnet.`)}
function refreshLedger(){const body=document.getElementById('ledger-body');if(body)body.innerHTML=ledgerRows();const count=document.getElementById('history-count');if(count)count.textContent=`${filteredEvents().length} Ereignisse`}
let toastTimer;
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500)}
async function copyConfig(){try{await navigator.clipboard.writeText(configText());toast('Beispiel-Konfiguration kopiert. Endpunkt und Token sind Platzhalter.')}catch{showOverlay(`${closeButton()}<h2>Konfiguration kopieren</h2><p>Die Zwischenablage ist hier nicht verfügbar. Markiere das Beispiel und kopiere es manuell.</p><textarea class="field" rows="11" readonly aria-label="MCP-Beispielkonfiguration">${escapeHtml(configText())}</textarea><button class="btn primary full" data-action="close">Schließen</button>`)}}
function exportEvents(){const data={prototype:true,dataset:'Studio Nord — fiktive Beispieldaten',workspace:state.workspace,timezone:'Europe/Rome',recorded_date:'2026-10-31',enabled_demo_sources:state.sources,event_count:events.length,events:events.map(({live,...e})=>e)};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='blackbox-demo-flugschreiber.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${events.length} Demo-Ereignisse als JSON exportiert.`)}
document.addEventListener('click',event=>{const actionEl=event.target.closest('[data-action]');if(!actionEl){if(event.target.matches('[data-dismiss="true"]'))closeOverlay();return}const action=actionEl.dataset.action,id=actionEl.dataset.id;
  if(action==='signup')showSignup();
  else if(action==='demo')navigate();
  else if(action==='close')closeOverlay();
  else if(action==='landing'){closeOverlay();location.hash='';window.scrollTo(0,0)}
  else if(action==='tab')navigate(id);
  else if(action==='event')eventDetail(id);
  else if(action==='about')about();
  else if(action==='open-agent')navigate('agents');
  else if(action==='onboarding'){state.selectedSources=[...state.sources];showOnboarding(1)}
  else if(action==='onboard-next'){if(state.onboardStep===1){state.selectedSources=Array.from(document.querySelectorAll('input[name="onboard-source"]:checked')).map(e=>e.value);if(!state.selectedSources.length){toast('Wähle mindestens eine Demo-Quelle.');return}}showOnboarding(state.onboardStep+1)}
  else if(action==='onboard-back')showOnboarding(state.onboardStep-1);
  else if(action==='onboard-agent'){state.agent=id;showOnboarding(3)}
  else if(action==='finish-onboard'){state.sources=[...state.selectedSources];persist();state.answer=null;navigate();toast('Dein Demo-Flugschreiber ist bereit.')}
  else if(action==='connect')connectionModal(id);
  else if(action==='toggle-source'){if(sources.find(s=>s.id===id)?.comingSoon)return;const connected=state.sources.includes(id);state.sources=connected?state.sources.filter(s=>s!==id):[...state.sources,id];persist();closeOverlay();renderApp();toast(connected?'Demo-Quelle getrennt. Die Historie bleibt erhalten.':'Demo-Quelle aktiviert.')}
  else if(action==='pause'){state.paused=!state.paused;const rec=document.querySelector('.recorder');if(rec)rec.innerHTML=recorderHTML()}
  else if(action==='simulate')addLiveEvent(true);
  else if(action==='ask')showAnswer(id);
  else if(action==='agent'){state.agent=id;document.getElementById('app-content').innerHTML=agentsPage()}
  else if(action==='copy-config')copyConfig();
  else if(action==='test-agent'){showOverlay(`${closeButton()}<div class="eyebrow" style="margin-bottom:17px">${icon('spark')}${escapeHtml(state.agent)} · SIMULIERTE ABFRAGE</div><h2>Gleiche Frage.<br>Gleicher Kontext.</h2><p>„Kann ich noch 100 Olive Cups verkaufen?“</p>${answerHTML('inventory')}<div class="demo-callout">Diese Antwort kommt aus dem Demo-Datensatz. Es wurde kein externer Agent oder MCP-Server aufgerufen.</div>`)}
  else if(action==='export')exportEvents();
  else if(action==='menu'){state.mobileMenu=!state.mobileMenu;document.querySelector('.sidebar')?.classList.toggle('mobile-open',state.mobileMenu);document.querySelector('.mobile-sidebar-overlay')?.classList.toggle('open',state.mobileMenu)}
  else if(action==='landing-question'){state.landingExample=id;document.querySelectorAll('.example-button').forEach(b=>b.classList.toggle('active',b.dataset.id===id));document.getElementById('landing-answer').innerHTML=`<div class="answer-preview-head"><span>${icon('spark')} blackbox / Antwort aus Beispieldaten</span>${icon('shield')}</div>${answerHTML(id,true)}`}
});
document.addEventListener('submit',event=>{if(event.target.id==='signup-form'){event.preventDefault();const name=new FormData(event.target).get('workspace').trim();if(!name){toast('Gib einen Namen für deinen Demo-Workspace ein.');return}state.workspace=name.slice(0,50);state.selectedSources=['shopify','email'];persist();showOnboarding(1)}if(event.target.id==='question-form'){event.preventDefault();const q=new FormData(event.target).get('question').trim().toLowerCase();if(!q)return;let type='unknown';if(/payment|provider|stripe|paypal|mollie|auszahl|payout|erstatt|refund|gebühr|gebuehr|streitfall|chargeback|einbehalt|autorisier/.test(q))type='payments';else if(/rechnung|invoice|lexware|sevdesk|easybill|billbee|sufio|gutschrift|mahnung|forderun|storno/.test(q))type='billing';else if(/paket|tracking|sendung|dhl|dpd|ups|shopware|sw.?200[12]|1036|zustell/.test(q))type='tracking';else if(/cash|liquid|geld|finanz|zahlung|konto|budget|umsatz/.test(q))type=/umsatz/.test(q)&&!/(cash|liquid|geld|zahlung|konto|budget)/.test(q)?'unknown':'cash';else if(/liefer|verspät|spaet|spät|po.?208|zusage|termin/.test(q))type='delivery';else if(/100|olive|cup|stück|stueck|bestand|verfüg|verfueg|verkauf|lager|reserv/.test(q))type='inventory';showAnswer(type)}});
document.addEventListener('input',event=>{if(event.target.id==='history-search'){state.historySearch=event.target.value;refreshLedger()}});
document.addEventListener('change',event=>{if(event.target.id==='history-type'){state.historyType=event.target.value;refreshLedger()}});
document.addEventListener('keydown',event=>{const overlay=document.getElementById('overlay-root');if(event.key==='Escape'){if(overlay.children.length)closeOverlay();else if(state.mobileMenu){state.mobileMenu=false;renderApp()}}if(event.key==='Tab'&&overlay.children.length){const focusables=Array.from(overlay.querySelectorAll('button,[href],input,select,textarea,[tabindex="0"]')).filter(el=>!el.disabled&&el.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',route);
setInterval(()=>{if(state.page!=='app'||state.paused||document.hidden)return;state.elapsed++;const time=document.getElementById('live-time');if(time)time.textContent=currentTime()+' · JETZT';if(state.elapsed%12===0)addLiveEvent()},1000);
seedTracking();
seedInvoices();
seedPayments();
route();
